package com.fitnutri.backend.summary;

import com.fasterxml.jackson.databind.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.support.TestDatabase;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.net.*;
import java.net.http.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;

/** Actual Session/CSRF/MVC/grouped PostgreSQL; this context deliberately has no external model or catalogue import. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) @ActiveProfiles("integration-test")
class SummaryHttpIntegrationTest {
    private static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
    @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
    @LocalServerPort int port;@Autowired UserRepository users;@Autowired FoodRecordRepository foods;@Autowired ExerciseRecordRepository exercises;
    private final ObjectMapper json=new ObjectMapper();private HttpClient client;private String csrf,email;
    @BeforeEach void signIn() throws Exception {client=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();csrf=null;email="summary-"+UUID.randomUUID()+"@example.test";csrf=status(200,send("GET","/api/auth/csrf",null)).get("token").asText();status(201,send("POST","/api/auth/register",Map.of("email",email,"password","Synthetic123","displayName","Synthetic summary")));status(200,send("POST","/api/auth/login",Map.of("email",email,"password","Synthetic123")));csrf=status(200,send("GET","/api/auth/csrf",null)).get("token").asText();var setup=settings(status(200,send("GET","/api/profile",null)),null);setup.put("initialWeight",Map.of("recordDate","2020-01-01","weightKg",70));status(200,send("POST","/api/profile/onboarding",setup));}
    private Map<String,Object> settings(JsonNode p,Integer target){var b=new LinkedHashMap<String,Object>();b.put("expectedUserVersion",p.get("user").get("version").asLong());b.put("expectedProfileVersion",p.get("profileVersion").isNull()?null:p.get("profileVersion").asLong());b.put("displayName","Synthetic summary");b.put("birthYear",1990);b.put("adultConfirmed",true);b.put("sex","PREFER_NOT_TO_SAY");b.put("heightCm",170);b.put("activityLevel","LIGHT");b.put("goalType",null);b.put("dailyTargetKj",target);b.put("energyUnit","KJ");b.put("healthSafetyAnswer","NO");b.put("qaConsentGranted",false);b.put("zone","Australia/Sydney");return b;}
    private HttpResponse<String> send(String method,String path,Object body) throws Exception {var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path));if(csrf!=null)r.header("X-CSRF-TOKEN",csrf);if(body!=null)r.header("Content-Type","application/json");return client.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
    private JsonNode status(int expected,HttpResponse<String> r) throws Exception {assertEquals(expected,r.statusCode(),r.body());return json.readTree(r.body());}
    private User owner(){return users.findByCanonicalEmail(email).orElseThrow();}
    private void food(LocalDate date,String energy){var r=new FoodRecord();r.setUser(owner());r.setFoodName("Synthetic legacy HTTP fixture");r.setRecordDate(date);r.setRecordedAt(Instant.parse("2026-10-16T10:00:00Z"));r.setSource(RecordSource.PHOTO);r.setClientEntryId(UUID.randomUUID());r.setQuantityGramsSnapshot(new BigDecimal("100"));r.setMealType(MealType.LUNCH);r.setEnergyKj(energy==null?null:new BigDecimal(energy));r.setCalories(999.0);foods.saveAndFlush(r);}
    private void threeDays(){food(LocalDate.of(2020,1,1),"100");food(LocalDate.of(2020,1,2),null);food(LocalDate.of(2020,1,3),"0");}
    private JsonNode trends() throws Exception {return status(200,send("GET","/api/summary/trends?from=2020-01-01&to=2020-01-03",null));}
    @Test void todayAndDailyShareCanonicalShapeWithoutDirectoryOrModelAndRequiredBoundsAreEnforced() throws Exception {
        status(503,send("GET","/api/food-reference/search?query=rice",null));var today=status(200,send("GET","/api/summary/today",null));var daily=status(200,send("GET","/api/summary/daily?date="+today.get("day").get("recordDate").asText(),null));assertEquals(today,daily);assertEquals(3,today.size());assertFalse(today.get("day").get("intake").get("hasData").asBoolean());assertTrue(today.get("day").get("intake").get("knownSum").isNull());assertFalse(today.has("caloriesRemaining"));status(400,send("GET","/api/summary/daily",null));status(400,send("GET","/api/summary/weekly?from=2020-01-01",null));status(400,send("GET","/api/summary/trends?from=2020-01-01&to=2020-01-03&days=3",null));status(400,send("GET","/api/summary/trends?from=2020-01-01",null));status(400,send("GET","/api/summary/trends?days=367",null));
    }
    @Test void groupedHttpSummaryPreservesHundredNullZeroAndMatchesOwnedHistory() throws Exception {threeDays();var period=trends();assertEquals(3,period.get("calendarDayCount").asInt());assertEquals(3,period.get("days").size());assertEquals(100,period.get("totals").get("intake").get("knownSum").asInt());assertEquals(2,period.get("totals").get("intake").get("knownValueCount").asInt());assertEquals(1,period.get("totals").get("intake").get("missingValueCount").asInt());assertEquals(2,period.get("totals").get("intake").get("legacyValueCount").asInt());assertTrue(period.get("totals").get("intake").get("partial").asBoolean());assertEquals(50,period.get("averages").get("intake").get("value").asInt());assertEquals(2,period.get("averages").get("intake").get("knownDayCount").asInt());assertTrue(period.get("days").get(1).get("intake").get("knownSum").isNull());assertEquals(0,period.get("days").get(2).get("intake").get("knownSum").asInt());var history=status(200,send("GET","/api/records/food?from=2020-01-01&to=2020-01-03",null));assertEquals(history.size(),period.get("totals").get("foodCount").asInt());}
    @Test void restrictedQaProfileStillReadsRulesAndExplicitTargetNeverOffsetsActivityEnergy() throws Exception {
        threeDays();var activity=new ExerciseRecord();activity.setUser(owner());activity.setExerciseType("Synthetic legacy activity");activity.setSource(RecordSource.MANUAL);activity.setDurationMinutes(BigDecimal.TEN);activity.setEstimatedKj(new BigDecimal("50"));activity.setRecordDate(LocalDate.of(2020,1,1));activity.setRecordedAt(Instant.parse("2026-10-16T10:00:00Z"));activity.setClientEntryId(UUID.randomUUID());exercises.saveAndFlush(activity);var profile=status(200,send("GET","/api/profile",null));assertFalse(profile.get("qaEligibility").get("eligible").asBoolean());assertTrue(trends().get("goalComparison").isNull());status(200,send("PUT","/api/profile",settings(profile,8400)));var period=trends();assertEquals(100,period.get("goalComparison").get("knownIntakeKj").asInt());assertEquals(2,period.get("goalComparison").get("comparedDays").asInt());assertEquals(16800,period.get("goalComparison").get("targetForComparedDaysKj").asInt());assertEquals(50,period.get("totals").get("expenditure").get("knownSum").asInt());assertTrue(period.get("facts").size()>0);
    }
    @Test void weeklyRangeDifferencesAndWeightFactsAreRecomputableFromRecordedInputs() throws Exception {
        threeDays();food(LocalDate.of(2019,12,31),"200");var weight=new LinkedHashMap<String,Object>();weight.put("recordDate","2020-01-03");weight.put("weightKg",71.25);weight.put("expectedVersion",null);weight.put("zone","Australia/Sydney");status(201,send("POST","/api/profile/weight",weight));var result=status(200,send("GET","/api/summary/weekly?end=2020-01-07",null));assertEquals("2020-01-01",result.get("current").get("rangeStart").asText());assertEquals("2019-12-25",result.get("previous").get("rangeStart").asText());assertEquals("2019-12-31",result.get("previous").get("rangeEnd").asText());JsonNode change=null,weightChange=null;for(var fact:result.get("current").get("facts")){if(fact.get("code").asText().equals("INTAKE_AVERAGE_CHANGE"))change=fact;if(fact.get("code").asText().equals("RECORDED_WEIGHT_CHANGE"))weightChange=fact;}assertNotNull(change);assertEquals(-150,change.get("values").get("difference").asInt());assertEquals(2,change.get("values").get("currentKnownDayCount").asInt());assertNotNull(weightChange);assertEquals(1.25,weightChange.get("values").get("changeKg").asDouble());
    }
    @Test void foreignOwnerQueryCannotOverrideSessionAndAnonymousReadsAre401() throws Exception {threeDays();Long previousOwner=owner().getId();signIn();var empty=status(200,send("GET","/api/summary/trends?from=2020-01-01&to=2020-01-03&userId="+previousOwner,null));assertEquals(0,empty.get("totals").get("foodCount").asInt());assertTrue(empty.get("totals").get("intake").get("knownSum").isNull());client=HttpClient.newHttpClient();assertEquals("UNAUTHENTICATED",status(401,send("GET","/api/summary/today",null)).get("code").asText());}
}
